class SmileyFixedFactory extends StyleDataDatabase{var$participant;function sql_dedicated_connection(){return new StyleDataConnection($this->participant);}}
foreach(array('active','implicit','inherited-lease')as$kind){
 sm_reset();$participant=new sql_db($host,'root',$password,$fixture,false);$factory=new SmileyFixedFactory($db->inner);$factory->participant=$participant;$before=sm_snapshot();$lease='attachment:'.md5($fixture."\0".ATTACHMENTS_TABLE);
 try{
  if($kind==='inherited-lease'){sd_check(phpbb_acl_rows($participant,"SELECT GET_LOCK('$lease',0) n")[0]['n']==='1','Factory participant owns its own lease');}
  else{sd_check($participant->sql_query($kind==='active'?'START TRANSACTION':'SET autocommit=0')&&$participant->sql_query("UPDATE fixture_themes SET style_name='Pending participant' WHERE themes_id=1"),'Factory participant owns pending work');}
  $state=phpbb_acl_rows($participant,'SELECT CONNECTION_ID() id,@@SESSION.autocommit a,@@SESSION.sql_mode m');$caught=false;try{phpbb_smilies_admin_change($factory,'save',sm_request('save'),$sd_root);}catch(PhpbbAclException$e){$caught=true;}
  sd_check($caught&&sm_snapshot()===$before&&phpbb_acl_rows($participant,'SELECT CONNECTION_ID() id,@@SESSION.autocommit a,@@SESSION.sql_mode m')===$state,'Rejected factory participant remains open and unchanged');
  if($kind==='inherited-lease'){sd_check(phpbb_acl_rows($peer,"SELECT IS_USED_LOCK('$lease') n")[0]['n']===$state[0]['id'],'Rejected participant retains its lease');phpbb_acl_rows($participant,"SELECT RELEASE_LOCK('$lease')");}
  else{sd_check(phpbb_acl_rows($participant,'SELECT style_name FROM fixture_themes WHERE themes_id=1')[0]['style_name']==='Pending participant'&&$participant->sql_query('ROLLBACK'),'Rejected participant retains data and rollback');}
 }finally{$participant->sql_close();}sd_unlocked();$cases++;
}
